  return (
    <ViewDrawer open={open} onClose={onClose} loading={isLoading} title={`Contact: ${contact.first_name} ${contact.last_name || ''}`.trim()}>
      <Tabs defaultActiveKey="personal" items={tabs} tabBarStyle={{ marginBottom: 16 }} />
